frappe.listview_settings['RRCL Employee'] = {
    onload: function(listview) {
        listview.page.add_action_item(__('Sync Employees'), function() {
            frappe.call({
                method: "rrcl.api.payroll_mauritius.sync_employees",
                callback: function(r) {
                    frappe.show_alert({message: __('Employees synced!'), indicator: 'green'});
                    listview.refresh();
                }
            });
        });
    }
};

frappe.listview_settings['RRCL Purchase Requisition'] = {
    onload(listview) {
        // Apply default filter only for RRCL Procurement Officer
        // frappe.session.user !== "Administrator" && 
        if (frappe.session.user !== "Administrator" && frappe.user.has_role("RRCL Procurement Officer")) {
            listview.filter_area.add([["RRCL Purchase Requisition", "workflow_state", "in", ['To Procure', 'Procurement in Progress']]]);
        }
    }
};

frappe.ui.form.on('RRCL Scaffolding Request', {
    refresh(frm) {
        frm.set_query("item", "table_yngh", function() {
            return {
                filters: {
                    category: "Scaffolding"
                }
            };
        });
    },
    calculate(frm) {
        if(!frm.doc.circumference || !frm.doc.height){
            msgprint("Please put circumference and height");
            return
        }
        frm.clear_table("table_yngh");
        frappe.db.get_list('RRCL Scaffolding Calculations', {
            fields: ["*"],
            limit: 0
        }).then(results => {
            results.forEach(item => {
                let row = frm.add_child("table_yngh");
                console.log(item)
                row.item = item.item;
                row.qty = Math.ceil(eval(item.formula.replace("c",frm.doc.circumference).replace("h",frm.doc.height)));
                row.construction_phase = "PH1",
                row.work_description = item.formula + "|" + item.formula.replace("c",frm.doc.circumference).replace("h",frm.doc.height)
                frm.script_manager.trigger("item", row.doctype, row.name);

            });
            frm.refresh_field("table_yngh");
        });
    }
});

